class Sum extends RecursiveTask<Long> {
    protected Long compute() {
        if (hi - lo < 10_000) return seqSum();          // leaf
        int mid = (lo + hi) >>> 1;
        Sum left = new Sum(lo, mid), right = new Sum(mid, hi);
        left.fork();                                    // fork one half
        long r = right.compute();                       // compute the other here
        return r + left.join();                         // join
    }
}
